<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(is_file(__DIR__.'/app/access_control_v1300.php'))require_once __DIR__.'/app/access_control_v1300.php';require_once __DIR__.'/app/classifieds_v1370.php';$me=sk1370_require_login('/classified-messages.php');$uid=sk1370_uid();$convs=sk1370_conversations($uid);$cid=(int)($_GET['c']??($convs[0]['id']??0));$msgs=$cid?sk1370_messages($cid,$uid):[];$current=null;foreach($convs as $c)if((int)$c['id']===$cid)$current=$c;sk1370_shell('Messages','messages');?><section class="messages-wrap"><aside><header><h2>Messages</h2><a href="/classifieds.php">Browse ads</a></header><?php if(!$convs):?><p class="empty">No conversations yet.</p><?php endif;foreach($convs as $c):$other=(int)$c['buyer_user_id']===$uid?(int)$c['seller_user_id']:(int)$c['buyer_user_id'];?><a class="conv <?=$cid==(int)$c['id']?'on':''?>" href="?c=<?=$c['id']?>"><span><?=sk1370_h(strtoupper(substr(sk1370_user_label($other),0,1)))?></span><div><b><?=sk1370_h(sk1370_user_label($other))?></b><small><?=sk1370_h($c['title'])?></small></div></a><?php endforeach;?></aside><section class="thread"><?php if(!$current):?><div class="empty full">Choose a conversation.</div><?php else:$other=(int)$current['buyer_user_id']===$uid?(int)$current['seller_user_id']:(int)$current['buyer_user_id'];?><header><div><b><?=sk1370_h(sk1370_user_label($other))?></b><small><?=sk1370_h($current['title'])?></small></div><a href="/classified.php?ad=<?=urlencode($current['slug'])?>">View ad</a></header><div class="message-list" id="skc-message-list"><?php foreach($msgs as $m):?><div class="bubble <?=((int)$m['sender_user_id']===$uid)?'mine':'theirs'?>"><p><?=nl2br(sk1370_h($m['body']))?></p><small><?=sk1370_h(date('d M, H:i',strtotime($m['created_at'])))?></small></div><?php endforeach;?></div><form class="message-compose" id="skc-message-form"><input type="hidden" name="conversation_id" value="<?=$cid?>"><textarea name="body" maxlength="1200" placeholder="Type a message…" required></textarea><button>Send</button></form><?php endif;?></section></section><?php sk1370_end();
